package com.cloudinfra.sdk.iam

import java.security.SecureRandom
import scala.collection.concurrent.TrieMap

// Permission bitmap constants
object Permissions {
  val READ: Int        = 0x00000001
  val WRITE: Int       = 0x00000002
  val DELETE: Int      = 0x00000004
  val ADMIN: Int       = 0x00000008
  val AUDIT: Int       = 0x00000010
  val PROVISION: Int   = 0x00000020
  val NETWORK: Int     = 0x00000040
  val BILLING: Int     = 0x00000080
  val SUPERUSER: Int   = 0x80000000
}

case class Role(name: String, permissionBits: Int)

case class Principal(id: String, roles: List[Role]) {
  // Compute effective permissions by combining all role permissions
  def effectivePermissions: Int = {
    roles.foldLeft(0) { (acc, role) => acc | role.permissionBits }
  }
}

// Resource quota tracking per principal
case class QuotaAllocation(principalId: String, resourceType: String, allocated: Int, limit: Int)

trait QuotaService {
  def checkAndAllocate(principal: Principal, resourceType: String, requestedCount: Int): Either[String, QuotaAllocation]
}

class CloudQuotaService extends QuotaService {
  private val allocations = TrieMap.empty[String, QuotaAllocation]
  private val random = new SecureRandom()

  private def quotaKey(principalId: String, resourceType: String): String =
    s"$principalId:$resourceType"

  // Base quota per permission level
  private def computeBaseQuota(principal: Principal): Long = {
    val perms = principal.effectivePermissions
    var quota = 10L // base quota for any authenticated user
    if ((perms & Permissions.PROVISION) != 0) quota += 50L
    if ((perms & Permissions.ADMIN) != 0) quota += 100L
    if ((perms & Permissions.SUPERUSER) != 0) quota += 500L
    quota
  }

  // Scaling factor based on number of roles (more roles = higher trust)
  private def trustMultiplier(principal: Principal): Long = {
    val roleCount = principal.roles.length
    // Each role adds a multiplier; capped conceptually at reasonable values
    // The multiplier scales the quota
    math.min(roleCount, 16).toLong
  }

  // Maximum allowed quota regardless of computation
  private val ABSOLUTE_MAX_QUOTA: Int = 10000

  // Compute the effective quota limit for a principal
  def effectiveQuotaLimit(principal: Principal): Int = {
    val base = computeBaseQuota(principal)
    val multiplier = trustMultiplier(principal)
    // Scale quota: base * multiplier * role_permission_weight
    // Use Long arithmetic to prevent overflow, then cap
    val roleWeight: Long = principal.roles.map(r => (r.permissionBits & 0xFFFFFFFFL)).sum
    // Final quota calculation in Long space
    val scaledQuota: Long = base * multiplier * roleWeight
    // Cap to absolute maximum to prevent abuse
    math.min(scaledQuota, ABSOLUTE_MAX_QUOTA.toLong).toInt
  }

  override def checkAndAllocate(
    principal: Principal,
    resourceType: String,
    requestedCount: Int
  ): Either[String, QuotaAllocation] = {
    if (requestedCount <= 0) return Left("Requested count must be positive")

    val key = quotaKey(principal.id, resourceType)
    val limit = effectiveQuotaLimit(principal)
    val current = allocations.get(key).map(_.allocated).getOrElse(0)

    // Check if allocation would exceed quota (safe: both are bounded positive Ints)
    val newTotal = current + requestedCount
    if (newTotal > limit || newTotal < 0) {
      Left(s"Quota exceeded: requested total $newTotal exceeds limit $limit")
    } else {
      val allocation = QuotaAllocation(principal.id, resourceType, newTotal, limit)
      allocations.put(key, allocation)
      Right(allocation)
    }
  }
}

// Access control gate that uses quota as a secondary authorization check
class ResourceProvisioner(quotaService: CloudQuotaService) {

  def provisionInstances(principal: Principal, count: Int): Either[String, String] = {
    // Primary RBAC check
    val perms = principal.effectivePermissions
    if ((perms & Permissions.PROVISION) == 0 && (perms & Permissions.ADMIN) == 0) {
      return Left("Insufficient permissions to provision resources")
    }

    // Secondary quota-based authorization
    quotaService.checkAndAllocate(principal, "compute_instances", count) match {
      case Right(alloc) =>
        Right(s"Provisioned $count instances. Total: ${alloc.allocated}/${alloc.limit}")
      case Left(err) =>
        Left(s"Provisioning denied: $err")
    }
  }
}

// Example usage
object CloudSDKDemo extends App {
  val quotaService = new CloudQuotaService()
  val provisioner = new ResourceProvisioner(quotaService)

  // Normal user with PROVISION permission
  val normalRole = Role("developer", Permissions.READ | Permissions.WRITE | Permissions.PROVISION)
  val normalUser = Principal("user-001", List(normalRole))

  // Even with crafted roles, quota is capped
  val attackRoles = (1 to 8).map { i =>
    Role(s"custom-role-$i", 0x10000000)
  }.toList
  val attackerPrincipal = Principal("attacker-002", attackRoles)

  println(s"Normal user quota: ${quotaService.effectiveQuotaLimit(normalUser)}")
  println(s"Attacker quota: ${quotaService.effectiveQuotaLimit(attackerPrincipal)}")

  println(provisioner.provisionInstances(attackerPrincipal, 999999))
}
